use std :: path :: Path ; use crate :: { Match , MatchResult } ; # [doc = " Truncates a key string for display purposes"] # [doc = ""] # [doc = " If the key length is 20 characters or less, returns it unchanged."] # [doc = " Otherwise, shows the first 13 characters and last 4 characters with \"...\" in"] # [doc = " between."] # [doc = ""] # [doc = " # Arguments"] # [doc = " * `key` - The key string to truncate"] # [doc = ""] # [doc = " # Returns"] # [doc = " * A truncated version of the key for safe display"] pub use forge_domain :: truncate_key ; use sha2 :: { Digest , Sha256 } ; use pretty_assertions :: assert_eq ; use serde_json :: json ; use super :: * ; fn normalize_array_items (map : & mut serde_json :: Map < String , serde_json :: Value > , strict_mode : bool) { if strict_mode && is_array_schema (map) && ! map . contains_key ("items") { map . insert ("items" . to_string () , serde_json :: json ! ({ "type" : "string" })) ; } }